<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/module2_helpers.php';
require_once __DIR__ . '/../../includes/functions.php';require_once __DIR__ . '/../../auth/guard.php';require_once __DIR__ . '/../../config/database.php';requireLogin();$id=(int)($_GET['id']??0);if($id<=0){setFlash('error','ID không hợp lệ.');redirect('/user/can-ho/index.php');}$s=$pdo->prepare('SELECT c.*,l.TenLoai FROM CanHo c JOIN LoaiCanHo l ON l.MaLoai=c.MaLoai WHERE c.MaCanHo=:id');$s->execute([':id'=>$id]);$can=$s->fetch();if(!$can){setFlash('error','Không tìm thấy căn hộ.');redirect('/user/can-ho/index.php');}$s=$pdo->prepare('SELECT * FROM CanHo_Anh WHERE MaCanHo=:id ORDER BY ThuTu,MaAnh');$s->execute([':id'=>$id]);$images=$s->fetchAll();$s=$pdo->prepare('SELECT h.*,k.HoTen TenKhach FROM HopDong h JOIN KhachThue k ON k.MaKhach=h.MaKhach WHERE h.MaCanHo=:id ORDER BY h.NgayBatDau DESC');$s->execute([':id'=>$id]);$contracts=$s->fetchAll();$title='Chi tiết căn '.$can['SoPhong'];require_once __DIR__ . '/../../includes/header.php';
?><div class="page-header"><div><h1>Căn hộ <?=e($can['SoPhong'])?></h1></div><div class="actions"><a class="btn btn-secondary" href="edit.php?id=<?=$id?>">Sửa</a><a class="btn btn-light" href="index.php">Quay lại</a></div></div><div class="detail-grid"><section class="detail-card"><h2>Thông tin</h2><div class="info-grid"><div><span>Mã căn</span><strong>#<?=$id?></strong></div><div><span>Số phòng</span><strong><?=e($can['SoPhong'])?></strong></div><div><span>Loại</span><strong><?=e($can['TenLoai'])?></strong></div><div><span>Trạng thái</span><?=renderStatusBadge($can['TrangThai'])?></div><div><span>Diện tích</span><strong><?=number_format((float)$can['DienTich'],2,',','.')?> m²</strong></div><div><span>Giá thuê</span><strong><?=formatMoney($can['GiaThue'])?></strong></div></div><div class="description"><span>Mô tả</span><p><?=nl2br(e($can['MoTa']??''))?></p></div></section><section class="detail-card"><h2>Ảnh căn hộ</h2><div class="image-grid"><?php foreach($images as $img):?><div class="image-item"><img src="<?=e(appUrl($img['DuongDan']))?>" alt="Ảnh căn hộ"><?php if((int)$img['LaAnhDaiDien']===1):?><span class="cover-label">Ảnh đại diện</span><?php endif;?></div><?php endforeach;?></div></section><section class="detail-card"><h2>Hợp đồng liên quan</h2><?php if(!$contracts):?><div class="empty-state">Chưa có hợp đồng.</div><?php else:?><div class="table-responsive"><table class="data-table"><thead><tr><th>Mã HĐ</th><th>Khách thuê</th><th>Bắt đầu</th><th>Kết thúc</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($contracts as $h):?><tr><td>#<?=$h['MaHopDong']?></td><td><?=e($h['TenKhach'])?></td><td><?=formatDate($h['NgayBatDau'])?></td><td><?=formatDate($h['NgayKetThuc'])?></td><td><?=renderStatusBadge($h['TrangThai'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php require_once __DIR__ . '/../../includes/footer.php'; ?>